/* Main loop */
static void run_matrix(void) {
    char *line[MAX_COLS];
    int x[MAX_COLS];
    int y[MAX_COLS];
    int active[MAX_COLS];
    int i;

    /* Initialize */
    for (i = 0; i < cols; i++) {
        line[i] = malloc(cols + 1);
        x[i] = 0;
        y[i] = 0;
        active[i] = 1;
        memset(line[i], ' ', cols);
        line[i][cols] = '\0';
    }

    /* Set initial color */
    current_color = 0;

    /* Main loop */
    while (running) {
        /* Update delay */
        usleep(update_delay * 100000);

        /* Update each line */
        for (i = 0; i < cols; i++) {
            if (active[i]) {
                /* Move character */
                if (x[i] >= cols - 1) {
                    x[i] = 0;
                    y[i] = (y[i] + 1) % rows;
                } else {
                    x[i]++;
                }

                /* Update character */
                if (char_change) {
                    line[i][x[i]] = get_random_char();
                }

                /* Print line */
                print_line(line[i], x[i], y[i], 0);
            }
        }

        /* Check for keystrokes (not in screensaver mode) */
        if (!screensaver_mode) {
            fd_set readfds;
            struct timeval tv;
            char buf[10];
            int n;

            FD_ZERO(&readfds);
            FD_SET(STDIN_FILENO, &readfds);
            tv.tv_sec = 0;
            tv.tv_usec = 100000;

            n = select(STDIN_FILENO + 1, &readfds, NULL, NULL, &tv);
            if (n > 0 && FD_ISSET(STDIN_FILENO, &readfds)) {
                n = read(STDIN_FILENO, buf, 1);
                if (n > 0) {
                    char c = buf[0];

                    if (c == 'q' || c == 'Q') {
                        running = 0;
                    } else if (c == 'a' || c == 'A') {
                        async_scroll = !async_scroll;
                    } else if (c == 'b' || c == 'B') {
                        bold_chars = !bold_chars;
                    } else if (c == 'n' || c == 'N') {
                        no_bold = !no_bold;
                    } else if (c >= '0' && c <= '9') {
                        update_delay = c - '0';
                    } else if (c == '!') {
                        current_color = 0;
                    } else if (c == '@') {
                        current_color = 1;
                    } else if (c == '#') {
                        current_color = 2;
                    } else if (c == '$') {
                        current_color = 3;
                    } else if (c == '%') {
                        current_color = 4;
                    } else if (c == '^') {
                        current_color = 5;
                    } else if (c == '&') {
                        current_color = 6;
                    } else if (c == ')') {
                        current_color = 7;
                    }
                }
            }
        }

        /* Check for screensaver mode exit */
        if (screensaver_mode) {
            fd_set readfds;
            struct timeval tv;

            FD_ZERO(&readfds);
            FD_SET(STDIN_FILENO, &readfds);
            tv.tv_sec = 0;
            tv.tv_usec = 100000;

            if (select(STDIN_FILENO + 1, &readfds, NULL, NULL, &tv) > 0) {
                running = 0;
            }
        }
    }

    /* Cleanup */
    for (i = 0; i < cols; i++) {
        free(line[i]);
    }
}
