+
+#include <stdio.h>
+#include <stdlib.h>
+#include <string.h>
+#include <unistd.h>
+#include <time.h>
+#include <termios.h>
+#include <sys/select.h>
+#include <sys/ioctl.h>
+#include <signal.h>
+#include <ctype.h>
+
+#define VERSION "2.0"
+#define DEFAULT_DELAY 4
+#define MAX_COLS 200
+#define MAX_ROWS 100
+
+/* Global configuration */
+static int async_scroll = 0;
+static int bold_chars = 0;
+static int all_bold = 0;
+static int no_bold = 0;
+static int linux_mode = 0;
+static int old_style = 0;
+static int rainbow_mode = 0;
+static int lambda_mode = 0;
+static int char_change = 0;
+static int screensaver_mode = 0;
+static int x_mode = 0;
+static int force_term = 0;
+static int use_japanese = 0;
+static int lock_mode = 0;
+
+static int update_delay = DEFAULT_DELAY;
+static char *color = "green";
+static char *tty = NULL;
+static char *message = NULL;
+
+/* Character sets */
+static const char *ascii_chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()_+-=[]{}|;:,.<>?";
+static const char *katakana_chars = "アァカサタナハマヤャラワガザダバパイィキシチニヒミリヰギジヂビピウゥクスツヌフムユュルグズブヅプエェケセテネヘメレヱゲゼデベペオォコソトノホモヨョロヲゴゾドボポヴッン";
+static const char *katakana_full = "アァカサタナハマヤャラワガザダバパイィキシチニヒミリヰギジヂビピウゥクスツヌフムユュルグズブヅプエェケセテネヘメレヱゲゼデベペオォコソトノホモヨョロヲゴゾドボポヴッン ン";
+
+static const char *color_chars[] = {
+    "green", "red", "blue", "white", "yellow", "cyan", "magenta", "black"
+};
+
+static int current_color = 0;
+
+/* Terminal state */
+static struct termios orig_termios;
+static int cols, rows;
+
+/* Message display */
+static int message_shown = 0;
+
+/* Signal handler */
+static volatile sig_atomic_t running = 1;
+
+void signal_handler(int sig) {
+    running = 0;
+}
+
+/* Get random character */
+static char get_random_char(void) {
+    if (lambda_mode) {
+        return 'λ';
+    }
+    if (use_japanese) {
+        return (char)katakana_chars[rand() % (strlen(katakana_full) - 1)];
+    }
+    return (char)ascii_chars[rand() % strlen(ascii_chars)];
+}
+
+/* Set terminal attributes */
+static void set_term_attrs(int enable) {
+    struct termios raw;
+    
+    if (tcgetattr(STDIN_FILENO, &orig_termios) == -1) {
+        return;
+    }
+    
+    if (enable) {
+        raw = orig_termios;
+        raw.c_lflag &= ~(ECHO | ICANON);
+        raw.c_cc[VMIN] = 0;
+        raw.c_cc[VTIME] = 0;
+        tcsetattr(STDIN_FILENO, TCSANOW, &raw);
+    } else {
+        tcsetattr(STDIN_FILENO, TCSANOW, &orig_termios);
+    }
+}
+
+/* Get terminal size */
+static void get_term_size(int *w, int *h) {
+    struct winsize ws;
+    if (ioctl(STDIN_FILENO, TIOCGWINSZ, &ws) == -1) {
+        *w = 80;
+        *h = 24;
+    } else {
+        *w = ws.ws_col;
+        *h = ws.ws_row;
+    }
+}
+
+/* Print a line with optional shadow */
+static void print_line(char *line, int x, int y, int shadow) {
+    int i;
+    
+    if (shadow) {
+        printf("\033[%d;%dH\033[2J", y + 1, x + 1);
+    }
+    
+    for (i = 0; i < cols; i++) {
+        int color_idx = current_color;
+        if (rainbow_mode) {
+            color_idx = (color_idx + 1) % 8;
+        }
+        
+        if (bold_chars && rand() % 100 < 5) {
+            printf("\033[%d;%dm%c", 1, 1 + color_idx * 2, line[i]);
+        } else if (all_bold) {
+            printf("\033[%d;%dm%c", 1, 1 + color_idx * 2, line[i]);
+        } else if (no_bold) {
+            printf("\033[%d;%dm%c", 0, 1 + color_idx * 2, line[i]);
+        } else {
+            printf("\033[%d;%dm%c", 0, 1 + color_idx * 2, line[i]);
+        }
+    }
+    printf("\033[0m\n");
+}
+
+/* Print message */
+static void print_message(void) {
+    if (message) {
+        printf("\033[H\033[1;37m%s\033[0m\n", message);
+        message_shown = 1;
+    }
+}
+
+/* Main loop */
+static void run_matrix(void) {
+    char *line[MAX_COLS];
+    int x[MAX_COLS];
+    int y[MAX_COLS];
+    int active[MAX_COLS];
+    int i;
+    
+    /* Initialize */
+    for (i = 0; i < cols; i++) {
+        line[i] = malloc(cols + 1);
+        x[i] = 0;
+        y[i] = 0;
+        active[i] = 1;
+        memset(line[i], ' ', cols);
+        line[i][cols] = '\0';
+    }
+    
+    /* Set initial color */
+    current_color = 0;
+    
+    /* Main loop */
+    while (running) {
+        /* Update delay */
+        usleep(update_delay * 100000);
+        
+        /* Update each line */
+        for (i = 0; i < cols; i++) {
+            if (active[i]) {
+                /* Move character */
+                if (x[i] >= cols - 1) {
+                    x[i] = 0;
+                    y[i] = (y[i] + 1) % rows;
+                } else {
+                    x[i]++;
+                }
+                
+                /* Update character */
+                if (char_change) {
+                    line[i][x[i]] = get_random_char();
+                }
+                
+                /* Print line */
+                print_line(line[i], x[i], y[i], 0);
+            }
+        }
+        
+        /* Check for keystrokes (not in screensaver mode) */
+        if (!screensaver_mode) {
+            fd_set readfds;
+            struct timeval tv;
+            char buf[10];
+            int n;
+            
+            FD_ZERO(&readfds);
+            FD_SET(STDIN_FILENO, &readfds);
+            tv.tv_sec = 0;
+            tv.tv_usec = 100000;
+            
+            n = select(STDIN_FILENO + 1, &readfds, NULL, NULL, &tv);
+            if (n > 0 && FD_ISSET(STDIN_FILENO, &readfds)) {
+                n = read(STDIN_FILENO, buf, 1);
+                if (n > 0) {
+                    char c = buf[0];
+                    
+                    if (c == 'q' || c == 'Q') {
+                        running = 0;
+                    } else if (c == 'a' || c == 'A') {
+                        async_scroll = !async_scroll;
+                    } else if (c == 'b' || c == 'B') {
+                        bold_chars = !bold_chars;
+                    } else if (c == 'n' || c == 'N') {
+                        no_bold = !no_bold;
+                    } else if (c >= '0' && c <= '9') {
+                        update_delay = c - '0';
+                    } else if (c == '!') {
+                        current_color = 0;
+                    } else if (c == '@') {
+                        current_color = 1;
+                    } else if (c == '#') {
+                        current_color = 2;
+                    } else if (c == '$') {
+                        current_color = 3;
+                    } else if (c == '%') {
+                        current_color = 4;
+                    } else if (c == '^') {
+                        current_color = 5;
+                    } else if (c == '&') {
+                        current_color = 6;
+                    } else if (c == ')') {
+                        current_color = 7;
+                    }
+                }
+            }
+        }
+        
+        /* Check for screensaver mode exit */
+        if (screensaver_mode) {
+            fd_set readfds;
+            struct timeval tv;
+            
+            FD_ZERO(&readfds);
+            FD_SET(STDIN_FILENO, &readfds);
+            tv.tv_sec = 0;
+            tv.tv_usec = 100000;
+            
+            if (select(STDIN_FILENO + 1, &readfds, NULL, NULL, &tv) > 0) {
+                running = 0;
+            }
+        }
+    }
+    
+    /* Cleanup */
+    for (i = 0; i < cols; i++) {
+        free(line[i]);
+    }
+}
+
+/* Print usage */
+static void print_usage(const char *prog) {
+    printf(" Usage: %s -[abBcfhlsmVxk] [-u delay] [-C color] [-t tty] [-M message]\n", prog);
+    printf(" -a: Asynchronous scroll\n");
+    printf(" -b: Bold characters on\n");
+    printf(" -B: All bold characters (overrides -b)\n");
+    printf(" -c: Use Japanese characters as seen in the original matrix. Requires appropriate fonts\n");
+    printf(" -f: Force the linux $TERM type to be on\n");
+    printf(" -l: Linux mode (uses matrix console font)\n");
+    printf(" -L: Lock mode (can be closed from another terminal)\n");
+    printf(" -o: Use old-style scrolling\n");
+    printf(" -h: Print usage and exit\n");
+    printf(" -n: No bold characters (overrides -b and -B, default)\n");
+    printf(" -s: \"Screensaver\" mode, exits on first keystroke\n");
+    printf(" -x: X window mode, use if your xterm is using mtx.pcf\n");
+    printf(" -V: Print version information and exit\n");
+    printf(" -M [message]: Prints your message in the center of the screen. Overrides -L's default message.\n");
+    printf(" -u delay (0 - 10, default 4): Screen update delay\n");
+    printf(" -C [color]: Use this color for matrix (default green)\n");
+    printf(" -r: rainbow mode\n");
+    printf(" -m: lambda mode\n");
+    printf(" -k: Characters change while scrolling. (Works without -o opt.)\n");
+    printf(" -t [tty]: Set tty to use\n");
+}
+
+/* Parse color */
+static int parse_color(const char *str) {
+    if (strcmp(str, "green") == 0) return 0;
+    if (strcmp(str, "red") == 0) return 1;
+    if (strcmp(str, "blue") == 0) return 2;
+    if (strcmp(str, "white") == 0) return 3;
+    if (strcmp(str, "yellow") == 0) return 4;
+    if (strcmp(str, "cyan") == 0) return 5;
+    if (strcmp(str, "magenta") == 0) return 6;
+    if (strcmp(str, "black") == 0) return 7;
+    return 0;
+}
+
+/* Parse delay */
+static int parse_delay(const char *str) {
+    int val = atoi(str);
+    if (val < 0) val = 0;
+    if (val > 10) val = 10;
+    return val;
+}
+
+int main(int argc, char *argv[]) {
+    int i;
+    int show_help = 0;
+    int show_version = 0;
+    
+    /* Parse arguments */
+    for (i = 1; i < argc; i++) {
+        if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "-?") == 0 || 
+            strcmp(argv[i], "--help") == 0) {
+            show_help = 1;
+        } else if (strcmp(argv[i], "-V") == 0 || strcmp(argv[i], "--version") == 0) {
+            show_version = 1;
+        } else if (strcmp(argv[i], "-a") == 0) {
+            async_scroll = 1;
+        } else if (strcmp(argv[i], "-b") == 0) {
+            bold_chars = 1;
+        } else if (strcmp(argv[i], "-B") == 0) {
+            all_bold = 1;
+            bold_chars = 1;
+        } else if (strcmp(argv[i], "-c") == 0) {
+            use_japanese = 1;
+        } else if (strcmp(argv[i], "-f") == 0) {
+            force_term = 1;
+        } else if (strcmp(argv[i], "-l") == 0) {
+            linux_mode = 1;
+        } else if (strcmp(argv[i], "-L") == 0) {
+            lock_mode = 1;
+        } else if (strcmp(argv[i], "-o") == 0) {
+            old_style = 1;
+        } else if (strcmp(argv[i], "-n") == 0) {
+            no_bold = 1;
+            bold_chars = 0;
+        } else if (strcmp(argv[i], "-s") == 0) {
+            screensaver_mode = 1;
+        } else if (strcmp(argv[i], "-x") == 0) {
+            x_mode = 1;
+        } else if (strcmp(argv[i], "-r") == 0) {
+            rainbow_mode = 1;
+        } else if (strcmp(argv[i], "-m") == 0) {
+            lambda_mode = 1;
+        } else if (strcmp(argv[i], "-k") == 0) {
+            char_change = 1;
+        } else if (strcmp(argv[i], "-u") == 0 && i + 1 < argc) {
+            update_delay = parse_delay(argv[++i]);
+        } else if (strcmp(argv[i], "-C") == 0 && i + 1 < argc) {
+            color = argv[++i];
+            current_color = parse_color(color);
+        } else if (strcmp(argv[i], "-M") == 0 && i + 1 < argc) {
+            message = argv[++i];
+        } else if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
+            tty = argv[++i];
+        } else {
+            fprintf(stderr, "Unknown option: %s\n", argv[i]);
+            return 1;
+        }
+    }
+    
+    /* Handle help and version */
+    if (show_help) {
+        print_usage(argv[0]);
+        return 0;
+    }
+    
+    if (show_version) {
+        printf(" CMatrix version %s (compiled 22:13:51, Jun 11 2026)\n", VERSION);
+        printf("Email: abishekvashok@gmail.com\n");
+        printf("Web: https://github.com/abishekvashok/cmatrix\n");
+        return 0;
+    }
+    
+    /* Set up signal handler */
+    signal(SIGINT, signal_handler);
+    signal(SIGTERM, signal_handler);
+    
+    /* Set terminal attributes */
+    set_term_attrs(1);
+    
+    /* Get terminal size */
+    get_term_size(&cols, &rows);
+    
+    /* Print message if specified */
+    if (message) {
+        print_message();
+    }
+    
+    /* Run the matrix effect */
+    run_matrix();
+    
+    /* Restore terminal attributes */
+    set_term_attrs(0);
+    
+    return 0;
+}
